class DetectSquares:
    def __init__(self):
        self.points = []

    def add(self, point):
        self.points.append((point[0], point[1]))

    def count(self, point):
        def occurrences(tx, ty):
            return sum(1 for x, y in self.points if x == tx and y == ty)
        qx, qy = point
        ans = 0
        for px, py in self.points:
            if px != qx and abs(px - qx) == abs(py - qy):
                ans += occurrences(px, qy) * occurrences(qx, py)
        return ans

