class DetectSquares {
public:
    DetectSquares() {}

    void add(vector<int> point) {
        pts.push_back({point[0], point[1]});
    }

    int count(vector<int> point) {
        int qx = point[0], qy = point[1], ans = 0;
        auto occ = [&](int x, int y) {
            int c = 0;
            for (auto& p : pts) if (p.first == x && p.second == y) c++;
            return c;
        };
        for (auto& [px, py] : pts)
            if (px != qx && abs(px - qx) == abs(py - qy))
                ans += occ(px, qy) * occ(qx, py);
        return ans;
    }

private:
    vector<pair<int, int>> pts;
};

