class DetectSquares {
    private List<int[]> pts = new ArrayList<>();

    public DetectSquares() {}

    public void add(int[] point) {
        pts.add(new int[]{point[0], point[1]});
    }

    public int count(int[] point) {
        int qx = point[0], qy = point[1], ans = 0;
        for (int[] p : pts) {
            int px = p[0], py = p[1];
            if (px != qx && Math.abs(px - qx) == Math.abs(py - qy)) {
                int c1 = 0, c2 = 0;
                for (int[] r : pts) {
                    if (r[0] == px && r[1] == qy) c1++;
                    if (r[0] == qx && r[1] == py) c2++;
                }
                ans += c1 * c2;
            }
        }
        return ans;
    }
}

