from collections import Counter

class DetectSquares:
    def __init__(self):
        self.cnt = Counter()
        self.unique = []

    def add(self, point):
        key = (point[0], point[1])
        self.cnt[key] += 1
        if self.cnt[key] == 1:
            self.unique.append(key)

    def count(self, point):
        qx, qy = point
        ans = 0
        for px, py in self.unique:
            if px != qx and abs(px - qx) == abs(py - qy):
                ans += self.cnt[(px, py)] * self.cnt[(px, qy)] * self.cnt[(qx, py)]
        return ans

