class DetectSquares {
    private Map<Long, Integer> cnt = new HashMap<>();
    private List<Long> uniqueKeys = new ArrayList<>();

    public DetectSquares() {}

    public void add(int[] point) {
        long key = point[0] * 1001L + point[1];
        cnt.merge(key, 1, Integer::sum);
        if (cnt.get(key) == 1) uniqueKeys.add(key);
    }

    public int count(int[] point) {
        int qx = point[0], qy = point[1], ans = 0;
        for (long key : uniqueKeys) {
            int px = (int)(key / 1001), py = (int)(key % 1001);
            if (px != qx && Math.abs(px - qx) == Math.abs(py - qy))
                ans += cnt.get(key)
                     * cnt.getOrDefault(px * 1001L + qy, 0)
                     * cnt.getOrDefault(qx * 1001L + py, 0);
        }
        return ans;
    }
}

