    this.cnt = new Map();
    this.uniqueKeys = [];
};

DetectSquares.prototype.add = function(point) {
    const key = point[0] * 1001 + point[1];
    this.cnt.set(key, (this.cnt.get(key) || 0) + 1);
    if (this.cnt.get(key) === 1) this.uniqueKeys.push(key);
};

DetectSquares.prototype.count = function(point) {
    const [qx, qy] = point;
    let ans = 0;
    for (const key of this.uniqueKeys) {
        const px = Math.floor(key / 1001), py = key % 1001;
        if (px !== qx && Math.abs(px - qx) === Math.abs(py - qy))
            ans += this.cnt.get(key)
                 * (this.cnt.get(px * 1001 + qy) || 0)
                 * (this.cnt.get(qx * 1001 + py) || 0);
    }
    return ans;
};
